import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: single main items ---
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a plain sword → base premium 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("a plain amulet → base premium 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("a plain staff → base premium 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("a plain potion → base premium 40 G + 4 G first insurance + 5 G fee = 49 G");

  // --- Components and the block of 3 alike ---
  it.todo("1 rune → base premium 25 G");
  it.todo("2 runes → base premium 50 G");
  it.todo("3 runes → base premium 60 G (block applies)");
  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
  it.todo("7 runes → base premium 175 G");
  it.todo("1 moonstone → base premium 25 G (components are priced alike)");
  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds a 50 % surcharge on that item's base premium (100 G → +50 G)");
  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (+30 G)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply (+50 G and +30 G)");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance adds a 10 % surcharge on the policy base premium");
  it.todo("the customer's second quote gets a 15 % follow-up contract discount");
  it.todo("each item in a quote is a first insurance even on a follow-up contract");

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
  );

  // --- Rounding ---
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // --- Integration examples (premium) ---
  it.todo("newcomer with a cursed sword (steel, enchantment 3), 0 years → premium 165 G");
  it.todo(
    "long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G",
  );

  // --- Claims: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
  it.todo("a claim reports remainingCap after the payout");

  // --- Claims: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo(
    "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold is ≥ 8)",
  );

  // --- Deductible per damage event ---
  it.todo(
    "dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // --- Payout rounding ---
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // --- Insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a cursed sword (premium 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo(
    "a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)",
  );

  // --- Cap exhaustion ---
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)");

  // --- Multiple items of the same type ---
  it.todo(
    "two swords insured, a dragon attack damages both → each damage entry gets its own deductible",
  );

  // --- Error cases ---
  it.todo("quote with an unknown item type (broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet when only a sword is insured) → error");
  it.todo("claim referencing a damage with an unknown item type → error");
  it.todo("claim with a damage amount of -200 → error");
  it.todo(
    "claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error",
  );

  // --- CLI ---
  it.todo("the CLI reads a scenario from stdin and writes {results:[...]} to stdout");
  it.todo("the CLI schema example yields a premium result then a payout/remainingCap result");
  it.todo("the CLI exits with a non-zero status and writes to stderr on an invalid scenario");
});

