export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const BLOCK_SIZE = 3;

const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
};

const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBasePremiumOf = (items: Item[]): number =>
  [...countByType(items)]
    .map(typeGroupBasePremiumOf)
    .reduce((sum, groupPremium) => sum + groupPremium, 0);

const quote = ({ items }: QuoteStep): QuoteResult => {
  const policyBase = policyBasePremiumOf(items);

  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;

  const premiumBeforeRounding =
    policyBase + firstInsuranceSurcharge + PROCESSING_FEE;

  return { premium: Math.ceil(premiumBeforeRounding) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step);

  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

