const LOYALTY_DISCOUNT_RATE = 0.2;

const LOYALTY_YEARS_THRESHOLD = 2;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

// Policy-wide modifiers apply to the policy base premium, so they are computed
// from the base alone — item-specific modifiers are not part of their base.
const policyModifiersOf = (policyBase: number, customer: Customer): number => {
  const loyaltyDiscount = isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;

  return policyBase * FIRST_INSURANCE_SURCHARGE_RATE - loyaltyDiscount;
};

const quote = ({ items }: QuoteStep, customer: Customer): QuoteResult => {
  const policyBase = policyBasePremiumOf(items);

  const premiumBeforeRounding =
    policyBase +
    itemModifiersOf(items) +
    policyModifiersOf(policyBase, customer) +
    PROCESSING_FEE;

  return { premium: Math.ceil(premiumBeforeRounding) };
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") return quote(step, customer);

  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

