  moonstone: 250,
};

const DEDUCTIBLE = 100;

const CAP_MULTIPLE = 2;

// A policy created by a quote step: what it covers, and how much of its
// payout cap is still available.
interface Policy {
  items: Item[];
  remainingCap: number;
}

const policyFor = (items: Item[]): Policy => {
  const insuranceSum = items.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0,
  );

  return { items, remainingCap: CAP_MULTIPLE * insuranceSum };
};

const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claim = ({ incident }: ClaimStep, policy: Policy): ClaimResult => {
  const payout = incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage),
    0,
  );

  policy.remainingCap -= payout;

  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
};

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
  const results: StepResult[] = [];

  const policies = new Map<number, Policy>();

  let precedingQuotes = 0;

  steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push(quote(step, { customer, precedingQuotes }));
      policies.set(index, policyFor(step.items));
      precedingQuotes += 1;

      return;
    }

    results.push(claim(step, policies.get(step.policy)!));
  });

  return { results };
};

